import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int CcPerBlock, int TILE_OH, int TILE_OW>
__global__ void dwconv2d_k1_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int K, int stride, int padding, int dilation,
    int Hout, int Wout,
    int TILE_IH, int TILE_IW,
    int num_oh_tiles, int num_ow_tiles)
{
  constexpr int OW_VEC = 4;
  constexpr int OH_VEC = 2;
  extern __shared__ unsigned char smem_raw[];
  T* sX = reinterpret_cast<T*>(smem_raw);                       // [CcPerBlock][TILE_IH][TILE_IW]
  T* sW = sX + (size_t)CcPerBlock * TILE_IH * TILE_IW;          // [CcPerBlock][K]
  const int n      = blockIdx.z;
  const int c_tile = blockIdx.y;
  const int c_base = c_tile * CcPerBlock;
  const int tile_idx = blockIdx.x;
  const int oh_tile  = tile_idx / num_ow_tiles;
  const int ow_tile  = tile_idx % num_ow_tiles;
  const int oh0 = oh_tile * TILE_OH;
  const int ow0 = ow_tile * TILE_OW;
  const int tx = threadIdx.x; // local ow group index (covers OW_VEC output columns)
  const int ty = threadIdx.y; // local oh group index (covers OH_VEC output rows)
  const int oh_local0 = ty * OH_VEC;
  const int ow_local0 = tx * OW_VEC;
  const int ow_start  = ow0 + ow_local0;
  const int ih_tile0 = oh0 * stride - padding;
  const int iw_tile0 = ow0 * stride - padding;
  const int blockDimX = TILE_OW / OW_VEC;
  const int blockDimY = TILE_OH / OH_VEC;
  const int tid      = ty * blockDimX + tx;
  const int nthreads = blockDimY * blockDimX;
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sYn = (int64_t)C * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  // Load weight chunk for this channel tile into shared memory
  const int wtotal = CcPerBlock * K;
  for (int idx = tid; idx < wtotal; idx += nthreads) {
    int cc = idx / K;
    int kk = idx % K;
    int c  = c_base + cc;
    T wval = T(0);
    if (c < C) {
      wval = W[(int64_t)c * K + kk];
    }
    sW[cc * K + kk] = wval;
  }
  // Cooperatively load the required input tile (with halo) into shared memory
  const int tile_elems = TILE_IH * TILE_IW;
  const int total_load = CcPerBlock * tile_elems;
  const T* Xn = X + (int64_t)n * sXn;
  if (stride == 1 && (TILE_IW % 4 == 0)) {
    const int TILE_IW_V = TILE_IW / 4;
    const int tile_elems_vec = TILE_IH * TILE_IW_V;
    const int total_load_vec = CcPerBlock * tile_elems_vec;
    for (int idx = tid; idx < total_load_vec; idx += nthreads) {
      int cc  = idx / tile_elems_vec;
      int rem = idx % tile_elems_vec;
      int r   = rem / TILE_IW_V;
      int cwv = rem % TILE_IW_V;
      int cw  = cwv * 4;
      int c   = c_base + cc;
      int ih  = ih_tile0 + r;
      int iw  = iw_tile0 + cw;
      float4 xv = make_float4(0.f, 0.f, 0.f, 0.f);
      if (c < C && ih >= 0 && ih < H) {
        const T* rowptr = &Xn[(int64_t)c * sXc + (int64_t)ih * Win];
        if (iw >= 0 && (iw + 3) < Win &&
            ((((size_t)(rowptr + iw)) & 0xF) == 0)) {
          xv = *reinterpret_cast<const float4*>(rowptr + iw);
        } else {
          float tmp[4] = {0.f, 0.f, 0.f, 0.f};
          #pragma unroll
          for (int t = 0; t < 4; ++t) {
            int iwt = iw + t;
            if (iwt >= 0 && iwt < Win) tmp[t] = (float)rowptr[iwt];
          }
          xv = make_float4(tmp[0], tmp[1], tmp[2], tmp[3]);
        }
      }
      T* dst = &sX[(size_t)cc * tile_elems + (size_t)r * TILE_IW + cw];
      *reinterpret_cast<float4*>(dst) = xv;
    }
  } else {
    for (int idx = tid; idx < total_load; idx += nthreads) {
      int cc  = idx / tile_elems;
      int rem = idx % tile_elems;
      int r   = rem / TILE_IW;
      int cw  = rem % TILE_IW;
      int c   = c_base + cc;
      int ih  = ih_tile0 + r;
      int iw  = iw_tile0 + cw;
      T xval = T(0);
      if (c < C && ih >= 0 && ih < H && iw >= 0 && iw < Win) {
        xval = Xn[(int64_t)c * sXc + (int64_t)ih * Win + iw];
      }
      sX[(size_t)cc * tile_elems + (size_t)r * TILE_IW + cw] = xval;
    }
  }
  __syncthreads();
  int oh_rows[OH_VEC];
  bool oh_valid[OH_VEC];
  int local_ih0[OH_VEC];
  #pragma unroll
  for (int r = 0; r < OH_VEC; ++r) {
    oh_rows[r] = oh0 + oh_local0 + r;
    oh_valid[r] = (oh_rows[r] < Hout);
    local_ih0[r] = (oh_local0 + r) * stride;
  }
  if (ow_start < Wout) {
    T* Yn = Y + (int64_t)n * sYn;
    #pragma unroll 4
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      int c = c_base + cc;
      if (c >= C) continue;
      float bias_val = 0.0f;
      if (B != nullptr) {
        bias_val = (float)B[c];
      }
      float acc[OH_VEC][OW_VEC];
      #pragma unroll
      for (int r = 0; r < OH_VEC; ++r) {
        #pragma unroll
        for (int t = 0; t < OW_VEC; ++t) acc[r][t] = bias_val;
      }
      for (int kk = 0; kk < K; ++kk) {
        float wval = (float)sW[cc * K + kk];
        #pragma unroll
        for (int r = 0; r < OH_VEC; ++r) {
          int row = local_ih0[r] + kk * dilation;
          if (row < 0 || row >= TILE_IH) continue;
          const T* sXrow = sX + (size_t)cc * tile_elems + (size_t)row * TILE_IW;
          #pragma unroll
          for (int t = 0; t < OW_VEC; ++t) {
            int local_iw = (ow_local0 + t) * stride;
            float xval = (float)sXrow[local_iw];
            acc[r][t] += xval * wval;
          }
        }
      }
      #pragma unroll
      for (int r = 0; r < OH_VEC; ++r) {
        if (!oh_valid[r]) continue;
        T* out_ptr = &Yn[(int64_t)c * sYc + (int64_t)oh_rows[r] * Wout + ow_start];
        bool full_vec = (ow_start + OW_VEC <= Wout) &&
                        ((((size_t)out_ptr) & 0xF) == 0);
        if (full_vec) {
          float4 vals = make_float4(acc[r][0], acc[r][1], acc[r][2], acc[r][3]);
          *reinterpret_cast<float4*>(out_ptr) = vals;
        } else {
          #pragma unroll
          for (int t = 0; t < OW_VEC; ++t) {
            int ow = ow_start + t;
            if (ow < Wout) {
              out_ptr[t] = static_cast<T>(acc[r][t]);
            }
          }
        }
      }
    }
  }
}
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C, 1, K, 1] for depthwise conv (groups=C)");
  int64_t N   = x.size(0);
  int64_t C   = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);
  TORCH_CHECK(w.size(0) == C, "w.size(0) must equal C");
  TORCH_CHECK(w.size(1) == 1, "w.size(1) must be 1 for depthwise");
  TORCH_CHECK(w.size(3) == 1, "w.size(3) must be 1 for (kernel_width=1)");
  int64_t K = w.size(2);
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (1 - 1) - 1) / stride + 1; // kw=1
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C, "bias must be [C]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, C, Hout, Wout}, x.options());
  constexpr int CcPerBlock = 2;
  constexpr int TILE_OH    = 16;
  constexpr int TILE_OW    = 32;
  constexpr int OW_VEC     = 4;
  constexpr int OH_VEC     = 2;
  const int TILE_IH = (int)((TILE_OH - 1) * (int64_t)stride + (K - 1) * (int64_t)dilation + 1);
  const int TILE_IW = (int)((TILE_OW - 1) * (int64_t)stride + 1);
  const int num_oh_tiles = (int)((Hout + TILE_OH - 1) / TILE_OH);
  const int num_ow_tiles = (int)((Wout + TILE_OW - 1) / TILE_OW);
  dim3 block(TILE_OW / OW_VEC, TILE_OH / OH_VEC);
  dim3 grid(
      (unsigned)(num_oh_tiles * num_ow_tiles),
      (unsigned)((C + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );
  size_t smem_bytes = (size_t)CcPerBlock * TILE_IH * TILE_IW * sizeof(float)
                    + (size_t)CcPerBlock * K * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(
        dwconv2d_k1_tiled_kernel<float, CcPerBlock, TILE_OH, TILE_OW>,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem_bytes);
  }
  dwconv2d_k1_tiled_kernel<float, CcPerBlock, TILE_OH, TILE_OW>
      <<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)K, (int)stride, (int)padding, (int)dilation,
      (int)Hout, (int)Wout,
      TILE_IH, TILE_IW,
      num_oh_tiles, num_ow_tiles
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "dwconv2d_k1_tiled_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

dwconv2d_ext = load_inline(
    name="cute_dwconv2d_k1_ext_model",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["dwconv2d_depthwise_k1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Depthwise 2D convolution with vertical asymmetric kernel (kernel_size x 1),
    implemented with a single custom CUDA kernel using CuTe.
    """
    def __init__(self,
                 in_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(dilation, int) and dilation >= 1

        self.in_channels = int(in_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)

        # Depthwise: groups = in_channels, out_channels = in_channels
        C = self.in_channels
        K = self.kernel_size
        # Weight shape matches PyTorch depthwise layout: [C_out, C_in/groups, Kh, Kw] with groups=C => [C,1,K,1]
        self.weight = nn.Parameter(torch.empty(C, 1, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(C))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = dwconv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.kernel_size  # depthwise per-channel fan_in equals kernel_size along H (Kw=1)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.dwconv2d_depthwise_k1_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
        )

